	defer C.free(unsafe.Pointer(carg1))

	cret = C.g_file_new_for_commandline_arg(carg1)
	runtime.KeepAlive(arg)

	var goret File

	goret = UnsafeFileFromGlibFull(unsafe.Pointer(cret))

	return goret
